namespace KnightOnline.Shared.Compression;

/// <summary>
/// Port of shared/lzf.c (liblzf 1.5, Marc Lehmann) in the exact configuration
/// the repo ships: HLOG=16, VERY_FAST=1, ULTRA_FAST=0, INIT_HTAB=0,
/// CHECK_INPUT=1, STRICT_ALIGN semantics (byte-wise compares).
///
/// Used by KOSocket::SendCompressed (WIZ_COMPRESS_PACKET) for large packets.
/// The compressed *format* is what the client cares about; this port also
/// happens to be byte-identical to the original output (verified against
/// golden vectors generated by compiling the unmodified lzf.c).
///
/// One deliberate difference: the C hash table starts as uninitialised stack
/// memory (INIT_HTAB=0). Garbage entries can only pass the
/// "ref &gt; in_data &amp;&amp; offset &lt; MAX_OFF" guards by astronomical accident,
/// so starting from an empty table is output-equivalent in practice.
/// We store (index + 1) so that 0 means "empty".
/// </summary>
public static class Lzf
{
    public const int Margin = 128; // LZF_MARGIN

    private const int HLog = 16;
    private const int HSize = 1 << HLog;
    private const int MaxLit = 1 << 5;          // 32
    private const int MaxOff = 1 << 13;         // 8192
    private const int MaxRef = (1 << 8) + (1 << 3); // 264

    private static uint Frst(ReadOnlySpan<byte> p, int i) => (uint)((p[i] << 8) | p[i + 1]);
    private static uint Next(uint v, ReadOnlySpan<byte> p, int i) => (v << 8) | p[i + 2];
    // VERY_FAST IDX
    private static int Idx(uint h) => (int)(((h >> (24 - HLog)) - h * 5) & (HSize - 1));

    /// <summary>
    /// Port of lzf_compress(). Returns the number of bytes written,
    /// or 0 if the output buffer is too small (or input is empty).
    /// </summary>
    public static int Compress(ReadOnlySpan<byte> input, Span<byte> output)
    {
        if (input.Length == 0 || output.Length == 0)
            return 0;

        var htab = new int[HSize]; // stores ip index + 1; 0 = empty
        var inLen = input.Length;
        var outLen = output.Length;

        var ip = 0;
        var op = 0;
        var lit = 0;
        op++; // start literal run (length byte written later)

        // C evaluates FRST(ip) even for tiny inputs (reading past the end);
        // the value is unused when the main loop never runs.
        var hval = inLen >= 2 ? Frst(input, 0) : 0u;

        while (ip < inLen - 2)
        {
            hval = Next(hval, input, ip);
            var slot = Idx(hval);
            var refIdx = htab[slot] - 1;
            htab[slot] = ip + 1;

            var off = ip - refIdx - 1;
            if (refIdx >= 1                       // ref > in_data
                && off >= 0 && off < MaxOff
                && ip + 4 < inLen
                && input[refIdx] == input[ip]
                && input[refIdx + 1] == input[ip + 1]
                && input[refIdx + 2] == input[ip + 2])
            {
                // Match found; bytes [0..2] already known equal. The C code's
                // unrolled loop lands on the first mismatch index (or maxlen).
                var maxlen = Math.Min(inLen - ip - 2, MaxRef);
                var len = 3;
                while (len < maxlen && input[refIdx + len] == input[ip + len])
                    len++;

                if (op + 3 + 1 >= outLen && op - (lit == 0 ? 1 : 0) + 3 + 1 >= outLen)
                    return 0;

                output[op - lit - 1] = (byte)(lit - 1); // stop literal run
                op -= lit == 0 ? 1 : 0;                 // undo run if length is zero

                len -= 2; // len is now #octets - 2 relative to first matched byte
                ip++;

                if (len < 7)
                {
                    output[op++] = (byte)((off >> 8) + (len << 5));
                }
                else
                {
                    output[op++] = (byte)((off >> 8) + (7 << 5));
                    output[op++] = (byte)(len - 7);
                }

                output[op++] = (byte)off;
                lit = 0;
                op++; // start new literal run

                ip += len + 1;

                if (ip >= inLen - 2)
                    break;

                // VERY_FAST: re-hash the last two positions of the match.
                ip--;
                ip--;
                hval = Frst(input, ip);
                hval = Next(hval, input, ip);
                htab[Idx(hval)] = ip + 1;
                ip++;

                hval = Next(hval, input, ip);
                htab[Idx(hval)] = ip + 1;
                ip++;
            }
            else
            {
                if (op >= outLen)
                    return 0;

                lit++;
                output[op++] = input[ip++];

                if (lit == MaxLit)
                {
                    output[op - lit - 1] = (byte)(lit - 1); // stop run
                    lit = 0;
                    op++; // start run
                }
            }
        }

        if (op + 3 > outLen)
            return 0;

        while (ip < inLen)
        {
            lit++;
            output[op++] = input[ip++];

            if (lit == MaxLit)
            {
                output[op - lit - 1] = (byte)(lit - 1);
                lit = 0;
                op++;
            }
        }

        output[op - lit - 1] = (byte)(lit - 1); // end run
        op -= lit == 0 ? 1 : 0;

        return op;
    }

    /// <summary>
    /// Port of lzf_decompress(). Returns the number of bytes written,
    /// or 0 on corrupt input / insufficient output space.
    /// (The KO server never decompresses client data, but the pair is kept
    /// together for tooling and tests.)
    /// </summary>
    public static int Decompress(ReadOnlySpan<byte> input, Span<byte> output)
    {
        var ip = 0;
        var op = 0;
        var inLen = input.Length;
        var outLen = output.Length;

        if (inLen == 0)
            return 0;

        while (ip < inLen)
        {
            uint ctrl = input[ip++];

            if (ctrl < (1 << 5)) // literal run
            {
                ctrl++;

                if (op + ctrl > outLen)
                    return 0;
                if (ip + ctrl > inLen)
                    return 0;

                input.Slice(ip, (int)ctrl).CopyTo(output[op..]);
                ip += (int)ctrl;
                op += (int)ctrl;
            }
            else // back reference
            {
                var len = (int)(ctrl >> 5);
                var refIdx = op - (int)((ctrl & 0x1F) << 8) - 1;

                if (ip >= inLen)
                    return 0;

                if (len == 7)
                {
                    len += input[ip++];
                    if (ip >= inLen)
                        return 0;
                }

                refIdx -= input[ip++];

                if (op + len + 2 > outLen)
                    return 0;
                if (refIdx < 0)
                    return 0;

                // Overlapping copies are intentional (run-length encoding).
                for (var i = 0; i < len + 2; i++)
                    output[op++] = output[refIdx++];
            }
        }

        return op;
    }

    /// <summary>Convenience wrapper mirroring KOSocket's buffer sizing (input + LZF_MARGIN).</summary>
    public static byte[] CompressToArray(ReadOnlySpan<byte> input)
    {
        var buffer = new byte[input.Length + Margin];
        var written = Compress(input, buffer);
        return written == 0 ? Array.Empty<byte>() : buffer[..written];
    }

    public static byte[] DecompressToArray(ReadOnlySpan<byte> input, int expectedLength)
    {
        var buffer = new byte[expectedLength];
        var written = Decompress(input, buffer);
        return written == 0 ? Array.Empty<byte>() : buffer[..written];
    }
}
